const events = [
  { id:'exhibit', title:'你们也是自愿的吗', location:'西岸 · 免费展览',
    text:['「找到一个免费展览。介绍写着打破观众与创作者的边界。」','入口递来两张胸牌。你的是“观众协调”，对方的是“协调观众”。','「一个对人，一个对事。」工作人员解释。一个抱纸箱的水果松了口气：「换班的终于到了。」'],
    choices:[['先帮十分钟','help','你们开始签到。十分钟后问接班人在哪，工作人员指向你们：「已经到了啊。」对方摘下胸牌：「十分钟不是一个工种。」'],['说明我们没有报名工作','clarify','工作人员指着报名页：“我愿成为本次活动的一部分。”对方：「我以为跟欢迎光临是一个意思。」旁边的水果抬头：「你们也是这么来的？」'],['我先走，你自己决定','leave','对方：「行，我问清楚再决定。」稍晚消息传来：「出来了。领了盒饭，不领无法核销退出。有一种预算用于艺术的味道。」']],
    echo:{help:'海报又来了：《离场也是一种参与》。对方：「这回你可能有内部价。先确认一下，这次买票还是入职？」',clarify:'海报又来了：《离场也是一种参与》。对方：「我们可能算联合创作者。上回一起退胸牌的那个水果也来问了。」',leave:'海报又来了：《离场也是一种参与》。对方：「这个你有经验。」你们约定下次离开前先说清楚，不默认必须一起行动。'} },
  { id:'coupon', title:'九块九的尊严', location:'徐家汇 · 商场',
    text:['「有张九块九的券，再不用就过期了。」','坐了四十分钟地铁，店员微笑指向小字：满三百可用。','「现在回去，车费就真的白花了。」对方盯着菜单，像在等一个亏损自行恢复。'],
    choices:[['不必为了车费再花三百','stop','对方沉默两秒：「有道理。止损这门课我可以旁听吗？」你们把菜单放回去，连同平台为你们规划的美好生活。'],['附近找一家能吃饱的小店','shop','拐角面馆没有会员等级。你们各吃一碗面，老板把葱花放在旁边：「自己决定。」今天终于有一项选择权。'],['看看凑单到底值不值','list','算完账，你们没买套餐，买了促销区的衣架。对方：「我缺的可能不是九块九，是暂停购物的能力。」']],
    echo:{stop:'「今天又有券，我直接删了。不是完全学会了，只是删的时候想起你那句话。」',shop:'「那家面馆还在。不必为了见面重新开发一个商圈。」你们有了一个不用提前查人均的地方。',list:'「你缺不缺七个衣架？我们上回共同投资的固定资产。」你们决定下次只带够吃饭的钱。'} },
  { id:'group', title:'群聊里的临时居民', location:'长宁 · 小区门口',
    text:['「误进隔壁业主群。我说了一句这个报价不合理。」','十分钟后，对方被任命为电梯维修监督组联络员。','「现在让我填门牌号。我住的是隔壁，严格说也算附近的群众。」'],
    choices:[['坦白身份后退出','truth','群主：「不是业主也可以关心社区。」对方：「关心不等于担任联络员。」最后退群前还被要求填一份离任满意度。'],['帮查报价，再说明身份','research','你们整理出三项不清楚的费用，注明只供参考。群里终于有人问供应商，没人再问门牌号。对方把联络员改成了“路过”。'],['先编一个门牌号','pretend','「三栋……」话没说完，对方划掉输入：「不行，再编就要参加明年业委会选举了。」你们决定现在解释，比以后解释一个不存在的家容易。']],
    echo:{truth:'「收到维修结果了。有人私聊说谢谢。原来退出组织也能有售后。」',research:'「电梯修好了。业主群发来感谢，抬头写热心路过。这个职称我可以接受。」',pretend:'「他们又问我要不要回群。我说我已经搬出那个虚构地址了。」你们约定，下次不用为了圆一句话住进另一种生活。'} },
  { id:'table', title:'不在菜单上的座位', location:'静安 · 社区长桌',
    text:['你们报名一场社区晚餐，分桌规则按水果外形制定。','对方指着座位卡：「我们是来吃饭的，不是来帮助主办方做果盘。」','主持人坚持说，这样“拍照更和谐”。你们面前的汤已经凉了。'],
    choices:[['问过同桌意见，一起换位','ask','大家同意按谁不吃香菜重新坐。主持人最终拍了一张看不出分类规则、但都在认真吃饭的照片。'],['明确提出不按品种分桌','speak','你们把座位卡翻面写上名字。对方：「我不想每次都解释整个族群。今天只解释我自己。」'],['尊重对方想离开的决定','exit','对方不想把晚饭变成辩论。你们去街边吃馄饨，没有拍照，也没有人为你们设计和谐。']],
    echo:{ask:'「那天同桌拉了一个群，群名叫不吃香菜也能坐一起。目前最大的分歧是饺子蘸不蘸醋。」',speak:'「主办方改报名表了。不过我不想每次见你都讨论这件事，下次聊点我喜欢的东西吧。」',exit:'「馄饨老板还记得我们不要葱。被记住这个，比被记住水果分类舒服一点。」'} }
];

