let musicState = "paused";
let noticeTimer;
const music = new MenuMusic(`${"public/"}${__menu.music.file}`, state => {
  musicState = state;
  updateMusic();
  if (state === "error") notify("音乐暂时无法加载，仍可正常使用菜单。请稍后再试。");
  if (state === "gesture") notify("请再次点击音乐按钮，允许浏览器播放。");
});
music.setVolume(0.4);

function notify(message, action) {
  const notice = document.querySelector("#notice");
  clearTimeout(noticeTimer);
  notice.replaceChildren();
  const copy = document.createElement("span");
  copy.className = "notice-copy";
  copy.textContent = message;
  notice.append(copy);
  if (action) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "notice-action";
    button.textContent = action.label;
    button.addEventListener("click", () => {
      clearTimeout(noticeTimer);
      notice.hidden = true;
      action.onClick();
    });
    notice.append(button);
  }
  notice.hidden = false;
  noticeTimer = setTimeout(() => { notice.hidden = true; }, action ? 8000 : 5000);
}

function updateMusic() {
  const playing = musicState === "playing";
  const button = document.querySelector("#sound-toggle");
  button.dataset.playing = String(playing);
  button.setAttribute("aria-pressed", String(playing));
  button.setAttribute("aria-busy", String(musicState === "loading"));
  const label = music.enabled ? "暂停背景音乐" : "播放背景音乐";
  button.setAttribute("aria-label", label);
  button.title = label;
}

function showScreen(screen) {
  if (screen !== "game") {
    clearTimeout(noticeTimer);
    const notice = document.querySelector("#notice");
    notice.hidden = true;
    notice.replaceChildren();
  }
  document.querySelector(".app-shell").dataset.screen = screen;
  for (const section of document.querySelectorAll("main > section")) section.hidden = section.id !== `${screen}-screen`;
  document.querySelector("#sound-toggle").disabled = screen === "exit";
  const heading = document.querySelector(`#${screen}-screen h1`);
  if (heading) {
    heading.tabIndex = -1;
    heading.focus({ preventScroll: true });
  }
  window.scrollTo(0, 0);
}

document.querySelector("#sound-toggle").addEventListener("click", async () => {
  await music.setEnabled(!music.enabled);
  updateMusic();
});
let game;
const ageDialog = document.querySelector('#age-confirm');
document.querySelector('#app-logo').addEventListener('click', () => ageDialog.showModal());
document.querySelector('#age-yes').addEventListener('click', () => {
  ageDialog.close();
  game ||= mountGame({ notify, onMenu: () => showScreen('menu') });
  showScreen('game');
  game.open();
});
async function declineAge(){
  ageDialog.close();
  await music.setEnabled(false);
  showScreen('exit');
}
document.querySelector('#age-no').addEventListener('click', declineAge);
ageDialog.addEventListener('cancel', event => { event.preventDefault(); declineAge(); });
document.querySelectorAll('.return-menu').forEach(button => button.addEventListener('click', () => showScreen('menu')));
updateMusic();
